function FPALIVE(i) local aa,P = FPAA,FPP local e = P(aa(FPD, (i or FPI)*4)); if not e then return false end local u = P(aa(e, 0x1EC)); if not u or u == "00000000" then return false end return (tonumber(ESE_ReadInt(aa(u, 0x178))) or 0) > 0 end function FPUNITALIVE(i) local aa,P = FPAA,FPP local e = P(aa(FPD, (i or FPI)*4)); if not e then return 0 end local u = P(aa(e, 0x1EC)); if not u or u == "00000000" then return 0 end return tonumber(ESE_ReadInt(aa(u, 0x178))) or 0 end function FPPICK(apply) local aa,P = FPAA,FPP local ex=tonumber(ESE_ReadFloat(aa(FPCAM,0x08))) local ey=tonumber(ESE_ReadFloat(aa(FPCAM,0x0C))) local ez=tonumber(ESE_ReadFloat(aa(FPCAM,0x10))) local fx=tonumber(ESE_ReadFloat(aa(FPCAM,0x60))) local fy=tonumber(ESE_ReadFloat(aa(FPCAM,0x64))) local fz=tonumber(ESE_ReadFloat(aa(FPCAM,0x68))) if not ex or not fx then return "no camera" end local best,bang,bd,bu = nil,1e9,0,nil local pick_any_army = FPPICKENEMY == true for i=0,FPCNT-1 do local e=P(aa(FPD,i*4)) if e then local x=tonumber(ESE_ReadFloat(aa(e,0x48))) local y=tonumber(ESE_ReadFloat(aa(e,0x4C))) local z=tonumber(ESE_ReadFloat(aa(e,0x50))) local un = 0 local same_army = true local u = P(aa(e,0x1EC)) if u and u ~= "00000000" then un = tonumber(ESE_ReadInt(aa(u,0x178))) or 0 if FPARMY and not pick_any_army then same_army = (P(aa(u,0x160)) == FPARMY) end else same_army = false end local liveok = (((un > 0) or FPPICKDEAD) and same_army) if liveok and x and y and z and x==x and math.abs(x)<2000 then local dx,dy,dz = x-ex, (y+0.9)-ey, z-ez local d=math.sqrt(dx*dx+dy*dy+dz*dz) if d>0.5 then local dot=(dx*fx+dy*fy+dz*fz)/d if dot>0 then local ang=math.acos(math.min(dot,1)) local score=ang + d*0.0004 if score<bang then bang=score best=i bd=d bu=u end end end end end end if not best then return "nothing in front of the camera" end FPPICK_MAN = best FPPICK_UNIT = bu if apply then FPI=best for k=1,20 do FPSTEP() end end return string.format("nearest friendly unit-strength-valid man to crosshair: %d dist=%.1f m unit=%s%s", best, bd, tostring(bu), apply and " -> HOOKED" or "") end function FPREHOOKFRIEND(apply) local aa,P = FPAA,FPP if not FPARMY then return "no FPARMY; run FPCMP(); FPCLAIMARMY() from the player side first" end local ex,ey,ez = 0,0,0 if FPCAM then ex=tonumber(ESE_ReadFloat(aa(FPCAM,0x08))) or 0 ey=tonumber(ESE_ReadFloat(aa(FPCAM,0x0C))) or 0 ez=tonumber(ESE_ReadFloat(aa(FPCAM,0x10))) or 0 end local best,bd,bu = nil,1e30,nil for i=0,FPCNT-1 do local e=P(aa(FPD,i*4)) if e then local u=P(aa(e,0x1EC)) if u and u ~= "00000000" and P(aa(u,0x160)) == FPARMY then local un=tonumber(ESE_ReadInt(aa(u,0x178))) or 0 local x=tonumber(ESE_ReadFloat(aa(e,0x48))) local y=tonumber(ESE_ReadFloat(aa(e,0x4C))) local z=tonumber(ESE_ReadFloat(aa(e,0x50))) if un > 0 and x and y and z and x==x and math.abs(x)<2000 then local dx,dy,dz=x-ex,y-ey,z-ez local d=dx*dx+dy*dy+dz*dz if d < bd then best=i bd=d bu=u end end end end end if not best then return "no strength-valid friendly man found" end FPPICK_MAN = best FPPICK_UNIT = bu if apply then FPI=best for k=1,20 do FPSTEP() end end return string.format("nearest friendly man: %d dist=%.1f m unit=%s%s", best, math.sqrt(bd), tostring(bu), apply and " -> HOOKED" or "") end return "FPPICK loaded"
